import { z } from "zod";

/* === ID === */

export const diagramIdSchema = z.string().min(1);

/* === Link === */

// The `id` values double as the generated JSON Schema `$defs` names, so every
// shared piece renders once and is referenced instead of copied per union member.
export const diagramLinkSchema = z
  .object({
    text: z.string().min(1).optional(),
    href: z.string().min(1),
  })
  .strict()
  .meta({ id: "Link" });
export type DiagramLink = z.infer<typeof diagramLinkSchema>;

/* === Route requirements === */

/** One route requirement: the control `controlId` must currently hold `value`. */
export const diagramRouteRequirementSchema = z
  .object({ controlId: diagramIdSchema, value: z.string().min(1) })
  .strict();
export type DiagramRouteRequirement = z.infer<typeof diagramRouteRequirementSchema>;

/** Route requirements joined by AND: the rule holds only when every requirement in it holds. */
export const diagramRouteRequirementRuleSchema = z.array(diagramRouteRequirementSchema);
export type DiagramRouteRequirementRule = z.infer<typeof diagramRouteRequirementRuleSchema>;

/** Rules joined by OR, in no particular order: the ruleset holds when any one rule holds. */
export const diagramRouteRequirementRulesetSchema = z
  .array(diagramRouteRequirementRuleSchema)
  .min(1)
  .meta({ id: "RouteRequirementRuleset" });
export type DiagramRouteRequirementRuleset = z.infer<typeof diagramRouteRequirementRulesetSchema>;

/* === Control === */

const diagramControlBaseShape = {
  controlId: diagramIdSchema,
  ownerNodeId: diagramIdSchema,
  label: z.string().min(1),
  // Omitted `dependsOn` equals [[]]: the control has no prerequisites. An
  // explicit [] stays invalid because an empty OR never holds.
  dependsOn: diagramRouteRequirementRulesetSchema.default([[]]),
};
export const diagramControlSchema = z.discriminatedUnion("type", [
  z.object({ ...diagramControlBaseShape, type: z.literal("conditional") }).strict(),
  z
    .object({
      ...diagramControlBaseShape,
      type: z.literal("branch"),
      cases: z.array(z.object({ caseId: diagramIdSchema, label: z.string().min(1) }).strict()).min(2),
      /** A boolean pair normalized to [ON, OFF] order. Case IDs keep their source meaning; consumers read the stored order rather than parsing labels. */
      polarityPair: z.boolean().default(false),
    })
    .strict(),
]);
export type DiagramControl = z.infer<typeof diagramControlSchema>;

/* === Node === */

const diagramNodeBaseShape = {
  nodeId: diagramIdSchema,
  title: z.string().min(1),
  groupId: diagramIdSchema.optional(),
  /** A generator-synthesized presentation element, not grounded in collected source. Parsing defaults it to false and serialization omits false. */
  synthetic: z.boolean().default(false),
};

export const defaultDiagramNodeSchema = z
  .object({
    ...diagramNodeBaseShape,
    description: z.string().min(1).optional(),
    details: z.array(z.string().min(1)).optional(),
    kind: z.string().min(1).optional(),
    type: z.literal("default").default("default"),
    links: z.array(diagramLinkSchema).optional(),
  })
  .strict()
  .meta({ id: "DefaultNode" });
export type DefaultDiagramNode = z.infer<typeof defaultDiagramNodeSchema>;

const activationEndpointSchema = z
  .object({
    messageId: diagramIdSchema,
    endpoint: z.enum(["source", "target"]),
  })
  .strict();
const activationSchema = z
  .object({
    activationId: diagramIdSchema,
    startsAt: activationEndpointSchema,
    endsAt: activationEndpointSchema,
  })
  .strict();
export const lifelineDiagramNodeSchema = z
  .object({
    ...diagramNodeBaseShape,
    description: z.string().min(1).optional(),
    details: z.array(z.string().min(1)).optional(),
    kind: z.string().min(1),
    type: z.literal("lifeline"),
    links: z.array(diagramLinkSchema).optional(),
    activations: z.array(activationSchema),
  })
  .strict()
  .meta({ id: "LifelineNode" });
export type LifelineDiagramNode = z.infer<typeof lifelineDiagramNodeSchema>;

const fragmentBranchSchema = z
  .object({
    branchId: diagramIdSchema,
    guard: z.string().min(1),
    startMessageId: diagramIdSchema,
    endMessageId: diagramIdSchema,
  })
  .strict();
export const fragmentDiagramNodeSchema = z
  .object({
    ...diagramNodeBaseShape,
    description: z.string().min(1).optional(),
    details: z.array(z.string().min(1)).optional(),
    kind: z.string().min(1),
    type: z.literal("fragment"),
    operator: z.enum(["alt", "opt", "loop", "par", "break", "critical", "assert", "neg"]),
    branches: z.array(fragmentBranchSchema).min(1),
  })
  .strict()
  .meta({ id: "FragmentNode" });
export type FragmentDiagramNode = z.infer<typeof fragmentDiagramNodeSchema>;

export const diamondDiagramNodeSchema = z
  .object({ ...diagramNodeBaseShape, type: z.literal("diamond") })
  .strict()
  .meta({ id: "DiamondNode" });
export type DiamondDiagramNode = z.infer<typeof diamondDiagramNodeSchema>;

export const diagramNodeSchema = z.discriminatedUnion("type", [
  defaultDiagramNodeSchema,
  diamondDiagramNodeSchema,
  lifelineDiagramNodeSchema,
  fragmentDiagramNodeSchema,
]);
export type DiagramNode = z.infer<typeof diagramNodeSchema>;

/* === Edge === */

export const defaultDiagramEdgeSchema = z
  .object({
    edgeId: diagramIdSchema,
    type: z.literal("default").default("default"),
    sourceNodeId: diagramIdSchema,
    targetNodeId: diagramIdSchema,
    kind: z.string().min(1).optional(),
    label: z.string().min(1).optional(),
    href: z.string().min(1).optional(),
  })
  .strict()
  .meta({ id: "DefaultEdge" });
export type DefaultDiagramEdge = z.infer<typeof defaultDiagramEdgeSchema>;

/** A composition gated by controls: the relationship applies when its `activeWhen` ruleset holds. */
export const controlDiagramEdgeSchema = z
  .object({
    edgeId: diagramIdSchema,
    type: z.literal("control"),
    sourceNodeId: diagramIdSchema,
    targetNodeId: diagramIdSchema,
    activeWhen: diagramRouteRequirementRulesetSchema,
  })
  .strict()
  .meta({ id: "ControlEdge" });
export type ControlDiagramEdge = z.infer<typeof controlDiagramEdgeSchema>;

export const messageDiagramEdgeSchema = z
  .object({
    edgeId: diagramIdSchema,
    type: z.literal("message"),
    sourceNodeId: diagramIdSchema,
    targetNodeId: diagramIdSchema,
    kind: z.string().min(1).optional(),
    label: z.string().min(1).optional(),
    href: z.string().min(1).optional(),
    messageType: z.enum(["sync", "async", "return"]).default("sync"),
  })
  .strict()
  .meta({ id: "MessageEdge" });
export type MessageDiagramEdge = z.infer<typeof messageDiagramEdgeSchema>;

export const diagramEdgeSchema = z.discriminatedUnion("type", [
  defaultDiagramEdgeSchema,
  controlDiagramEdgeSchema,
  messageDiagramEdgeSchema,
]);
export type DiagramEdge = z.infer<typeof diagramEdgeSchema>;

/** The optional display fields an authored edge carries; `control` edges state their condition in `activeWhen` instead. */
export function diagramEdgeDisplay(edge: DiagramEdge): Readonly<{ label?: string; kind?: string; href?: string }> {
  return edge.type === "control" ? {} : edge;
}

/* === Group === */

const diagramGroupBaseShape = {
  groupId: diagramIdSchema,
  title: z.string().min(1),
  parentGroupId: diagramIdSchema.optional(),
  /** A generator-synthesized presentation element, not grounded in collected source. Parsing defaults it to false and serialization omits false. */
  synthetic: z.boolean().default(false),
};

export const defaultDiagramGroupSchema = z
  .object({
    ...diagramGroupBaseShape,
    type: z.literal("default").default("default"),
    description: z.string().min(1).optional(),
  })
  .strict()
  .meta({ id: "DefaultGroup" });
export type DefaultDiagramGroup = z.infer<typeof defaultDiagramGroupSchema>;

export const boundingDiagramGroupSchema = z
  .object({
    ...diagramGroupBaseShape,
    type: z.literal("bounding"),
    description: z.string().min(1).optional(),
    hideTitle: z.boolean().default(false),
  })
  .strict()
  .meta({ id: "BoundingGroup" });
export type BoundingDiagramGroup = z.infer<typeof boundingDiagramGroupSchema>;

export const diagramGroupSchema = z.discriminatedUnion("type", [defaultDiagramGroupSchema, boundingDiagramGroupSchema]);
export type DiagramGroup = z.infer<typeof diagramGroupSchema>;

/* === Graph === */

type GraphIssue = Readonly<{ code: "custom"; path?: (string | number)[]; message: string }>;

/**
 * Integrity every graph shares regardless of layout: element ids are unique,
 * group hierarchies reference existing parents without cycling, nodes belong
 * to known groups, and edges connect existing nodes.
 */
function validateGraphIntegrity(graph: DiagramGraphLike): readonly GraphIssue[] {
  const issues: GraphIssue[] = [];
  const graphElements = [
    ...graph.groups.map((element, index) => ({
      element,
      key: element.groupId,
      path: ["groups", index, "groupId"] as const,
    })),
    ...graph.nodes.map((element, index) => ({
      element,
      key: element.nodeId,
      path: ["nodes", index, "nodeId"] as const,
    })),
    ...graph.edges.map((element, index) => ({
      element,
      key: element.edgeId,
      path: ["edges", index, "edgeId"] as const,
    })),
  ];
  const elementIds = new Set<string>();
  graphElements.forEach(({ key, path }) => {
    if (elementIds.has(key)) {
      issues.push({ code: "custom", path: [...path], message: `Duplicate diagram element ID: ${key}` });
    }
    elementIds.add(key);
  });

  const groupIds = new Set(graph.groups.map(({ groupId }) => groupId));
  const nodeById = new Map(graph.nodes.map((node) => [node.nodeId, node]));
  const groupById = Object.fromEntries(graph.groups.map((group) => [group.groupId, group]));

  graph.groups.forEach((group, index) => {
    if (group.parentGroupId && !groupIds.has(group.parentGroupId)) {
      issues.push({
        code: "custom",
        path: ["groups", index, "parentGroupId"],
        message: `Diagram group ${group.groupId} has unknown parent ${group.parentGroupId}`,
      });
    }
  });

  const containsGroupCycle = (groupId: string, ancestors: readonly string[]): boolean => {
    const group = groupById[groupId];
    if (!group?.parentGroupId) return false;
    if (ancestors.includes(group.parentGroupId)) return true;
    return containsGroupCycle(group.parentGroupId, [...ancestors, group.parentGroupId]);
  };

  if (graph.groups.some(({ groupId }) => containsGroupCycle(groupId, [groupId]))) {
    issues.push({ code: "custom", path: ["groups"], message: "Diagram group hierarchy contains a cycle" });
  }

  graph.nodes.forEach((node, index) => {
    if (node.groupId && !groupIds.has(node.groupId)) {
      issues.push({
        code: "custom",
        path: ["nodes", index, "groupId"],
        message: `Diagram node ${node.nodeId} belongs to unknown group ${node.groupId}`,
      });
    }
  });

  graph.edges.forEach((edge, index) => {
    const source = nodeById.get(edge.sourceNodeId);
    const target = nodeById.get(edge.targetNodeId);
    if (!source) {
      issues.push({
        code: "custom",
        path: ["edges", index, "sourceNodeId"],
        message: `Diagram edge ${edge.edgeId} sources unknown node ${edge.sourceNodeId}`,
      });
    }
    if (!target) {
      issues.push({
        code: "custom",
        path: ["edges", index, "targetNodeId"],
        message: `Diagram edge ${edge.edgeId} targets unknown node ${edge.targetNodeId}`,
      });
    }
    // A message edge connects two lifelines wherever it appears, not only in
    // the sequence contract.
    if (edge.type === "message") {
      if (source?.type !== "lifeline") {
        issues.push({
          code: "custom",
          path: ["edges", index, "sourceNodeId"],
          message: `Message edge ${edge.edgeId} source must be a lifeline`,
        });
      }
      if (target?.type !== "lifeline") {
        issues.push({
          code: "custom",
          path: ["edges", index, "targetNodeId"],
          message: `Message edge ${edge.edgeId} target must be a lifeline`,
        });
      }
    }
  });
  return issues;
}

type DiagramGraphLike = Readonly<{
  groups: readonly DiagramGroup[];
  nodes: readonly DiagramNode[];
  edges: readonly DiagramEdge[];
}>;

const graphBaseShape = {
  groups: z.array(diagramGroupSchema).readonly(),
  nodes: z.array(diagramNodeSchema).min(1).readonly(),
  edges: z.array(diagramEdgeSchema).readonly(),
};

/** The general graph contract: any node and edge kinds the diagram schemas define. */
export const generalDiagramGraphSchema = z
  .object(graphBaseShape)
  .strict()
  .superRefine((graph, context) => {
    for (const issue of validateGraphIntegrity(graph)) context.addIssue(issue);
  })
  .meta({ id: "GeneralDiagramGraph" });
export type GeneralDiagramGraph = z.infer<typeof generalDiagramGraphSchema>;

/** The flowchart contract: the general graph narrowed to rectangle and diamond nodes with default edges. Keyed by generator, not layout, because the flowchart generator shares the general layout. */
export const flowchartDiagramGraphSchema = z
  .object({
    ...graphBaseShape,
    nodes: z
      .array(z.discriminatedUnion("type", [defaultDiagramNodeSchema, diamondDiagramNodeSchema]))
      .min(1)
      .readonly(),
    edges: z.array(defaultDiagramEdgeSchema).readonly(),
  })
  .strict()
  .superRefine((graph, context) => {
    for (const issue of validateGraphIntegrity(graph)) context.addIssue(issue);
  })
  .meta({ id: "FlowchartGraph" });
export type FlowchartDiagramGraph = z.infer<typeof flowchartDiagramGraphSchema>;

/* === Layout-specific graphs === */

/** Sequence integrity: activations and fragment branches reference messages in span order. */
function validateSequenceGraph(graph: SequenceDiagramGraph): readonly GraphIssue[] {
  const issues: GraphIssue[] = [];
  const messageEdges = graph.edges.filter((edge): edge is MessageDiagramEdge => edge.type === "message");
  const messageById = new Map(messageEdges.map((edge) => [edge.edgeId, edge]));
  const messageIndexes = new Map(messageEdges.map((edge, index) => [edge.edgeId, index]));

  graph.nodes.forEach((node, index) => {
    if (node.type === "lifeline") {
      const activationIds = new Set<string>();
      node.activations.forEach((activation, activationIndex) => {
        if (activationIds.has(activation.activationId)) {
          issues.push({
            code: "custom",
            path: ["nodes", index, "activations", activationIndex, "activationId"],
            message: `Duplicate activation ID: ${activation.activationId}`,
          });
        }
        activationIds.add(activation.activationId);

        for (const [boundaryName, boundary] of [
          ["startsAt", activation.startsAt],
          ["endsAt", activation.endsAt],
        ] as const) {
          const message = messageById.get(boundary.messageId);
          if (!message) {
            issues.push({
              code: "custom",
              path: ["nodes", index, "activations", activationIndex, boundaryName, "messageId"],
              message: `Activation ${activation.activationId} references unknown message ${boundary.messageId}`,
            });
            continue;
          }

          const endpointNodeId = boundary.endpoint === "source" ? message.sourceNodeId : message.targetNodeId;
          if (endpointNodeId !== node.nodeId) {
            issues.push({
              code: "custom",
              path: ["nodes", index, "activations", activationIndex, boundaryName],
              message: `Activation ${activation.activationId} ${boundaryName} does not belong to lifeline ${node.nodeId}`,
            });
          }
        }

        const startIndex = messageIndexes.get(activation.startsAt.messageId);
        const endIndex = messageIndexes.get(activation.endsAt.messageId);
        if (startIndex !== undefined && endIndex !== undefined && startIndex > endIndex) {
          issues.push({
            code: "custom",
            path: ["nodes", index, "activations", activationIndex],
            message: `Activation ${activation.activationId} ends before it starts`,
          });
        }
      });
    }

    if (node.type === "fragment") {
      const branchIds = new Set<string>();
      node.branches.forEach((branch, branchIndex) => {
        if (branchIds.has(branch.branchId)) {
          issues.push({
            code: "custom",
            path: ["nodes", index, "branches", branchIndex, "branchId"],
            message: `Duplicate fragment branch ID: ${branch.branchId}`,
          });
        }
        branchIds.add(branch.branchId);

        const startIndex = messageIndexes.get(branch.startMessageId);
        const endIndex = messageIndexes.get(branch.endMessageId);
        if (startIndex === undefined || endIndex === undefined) {
          if (startIndex === undefined) {
            issues.push({
              code: "custom",
              path: ["nodes", index, "branches", branchIndex, "startMessageId"],
              message: `Fragment branch ${branch.branchId} references unknown message ${branch.startMessageId}`,
            });
          }
          if (endIndex === undefined) {
            issues.push({
              code: "custom",
              path: ["nodes", index, "branches", branchIndex, "endMessageId"],
              message: `Fragment branch ${branch.branchId} references unknown message ${branch.endMessageId}`,
            });
          }
        } else if (startIndex > endIndex) {
          issues.push({
            code: "custom",
            path: ["nodes", index, "branches", branchIndex],
            message: `Fragment branch ${branch.branchId} ends before it starts`,
          });
        }
      });
    }
  });
  return issues;
}

export const sequenceDiagramGraphSchema = z
  .object({
    ...graphBaseShape,
    nodes: z
      .array(z.discriminatedUnion("type", [lifelineDiagramNodeSchema, fragmentDiagramNodeSchema]))
      .min(1)
      .readonly(),
    edges: z.array(messageDiagramEdgeSchema).readonly(),
  })
  .strict()
  .superRefine((graph, context) => {
    const issues = [
      ...validateGraphIntegrity(graph),
      ...validateSequenceGraph(graph),
      ...(graph.groups.length > 0
        ? [{ code: "custom" as const, path: ["groups"], message: "Sequence layout does not support diagram groups" }]
        : []),
      ...(!graph.nodes.some((node) => node.type === "lifeline")
        ? [{ code: "custom" as const, path: ["nodes"], message: "Sequence layout requires at least one lifeline" }]
        : []),
    ];
    for (const issue of issues) context.addIssue(issue);
  })
  .meta({ id: "SequenceGraph" });
export type SequenceDiagramGraph = z.infer<typeof sequenceDiagramGraphSchema>;

export const dependencyDiagramGraphSchema = z
  .object({
    ...graphBaseShape,
    groups: z.array(defaultDiagramGroupSchema).readonly(),
    nodes: z.array(defaultDiagramNodeSchema).min(1).readonly(),
    edges: z.array(defaultDiagramEdgeSchema).readonly(),
  })
  .strict()
  .superRefine((graph, context) => {
    for (const issue of validateGraphIntegrity(graph)) context.addIssue(issue);
  })
  .meta({ id: "DependencyGraph" });
export type DependencyDiagramGraph = z.infer<typeof dependencyDiagramGraphSchema>;

/** Component provenance: the original supplier and slot, shared by node aggregates and edge compositions. */
const componentOriginSchema = z
  .object({ supplierDefinitionId: diagramIdSchema, slot: z.string().min(1) })
  .strict()
  .meta({ id: "ComponentOrigin" });

/** A named definition kept for display even though the graph has no node for it. */
const auxiliaryDefinitionSchema = z
  .object({ definitionId: diagramIdSchema, title: z.string().min(1) })
  .strict()
  .meta({ id: "AuxiliaryDefinition" });
export type AuxiliaryDefinition = z.infer<typeof auxiliaryDefinitionSchema>;

const componentStructureNodeLayoutContextSchema = z
  .object({
    definitionId: diagramIdSchema,
    origins: z.array(componentOriginSchema),
  })
  .strict();

export const componentStructureDiagramNodeSchema = defaultDiagramNodeSchema.extend({
  layoutContext: componentStructureNodeLayoutContextSchema.optional(),
});
export type ComponentStructureDiagramNode = z.infer<typeof componentStructureDiagramNodeSchema>;

/** A non-default composition, with the consumer slot separate from the original suppliers' slots. */
export const componentCompositionSchema = z
  .object({
    type: z.enum(["node", "render", "component"]),
    slot: z.string().min(1).optional(),
    origins: z.array(componentOriginSchema),
  })
  .strict()
  .meta({ id: "ComponentComposition" });
export type ComponentComposition = z.infer<typeof componentCompositionSchema>;

/** Omitted or null composition means direct rendering; objects describe other supply methods. */
const componentStructureEdgeLayoutContextSchema = z
  .object({ composition: componentCompositionSchema.nullable().default(null) })
  .strict()
  .meta({ id: "ComponentStructureEdgeLayoutContext" });
const componentStructureDefaultEdgeSchema = defaultDiagramEdgeSchema
  .extend({ layoutContext: componentStructureEdgeLayoutContextSchema.prefault({}) })
  .meta({ id: "ComponentStructureDefaultEdge" });
const componentStructureControlEdgeSchema = controlDiagramEdgeSchema
  .extend({ layoutContext: componentStructureEdgeLayoutContextSchema.prefault({}) })
  .meta({ id: "ComponentStructureControlEdge" });

/** Graph-level layout context for component structure: its roots and controls. */
export const componentStructureLayoutContextSchema = z
  .object({
    rootNodeIds: z.array(diagramIdSchema).min(1).readonly(),
    controls: z.array(diagramControlSchema).readonly(),
    // Recommended for referenced definitions without a node; registering a
    // definition that also has a node is allowed, and so is omitting entries.
    auxiliaryDefinitions: z.array(auxiliaryDefinitionSchema).readonly().default([]),
  })
  .strict();
export type ComponentStructureLayoutContext = z.infer<typeof componentStructureLayoutContextSchema>;

/** Component structure integrity: declared roots and controls agree with the stored relationships. */
function validateComponentStructureGraph(graph: ComponentStructureDiagramGraph): readonly GraphIssue[] {
  const issues: GraphIssue[] = [];
  const { rootNodeIds: roots, controls } = graph.layoutContext;
  const controlsById = new Map(controls.map((control) => [control.controlId, control]));
  const nodeIds = new Set(graph.nodes.map((node) => node.nodeId));

  const rootIds = new Set<string>();
  roots.forEach((root, index) => {
    if (!nodeIds.has(root) || rootIds.has(root)) {
      issues.push({
        code: "custom",
        path: ["layoutContext", "rootNodeIds", index],
        message: `${nodeIds.has(root) ? "Duplicate" : "Unknown"} component root: ${root}`,
      });
    }
    rootIds.add(root);
  });

  const controlIds = new Set<string>();
  controls.forEach((control, index) => {
    if (controlIds.has(control.controlId)) {
      issues.push({
        code: "custom",
        path: ["layoutContext", "controls", index, "controlId"],
        message: `Duplicate component control: ${control.controlId}`,
      });
    }
    controlIds.add(control.controlId);
    if (!nodeIds.has(control.ownerNodeId)) {
      issues.push({
        code: "custom",
        path: ["layoutContext", "controls", index, "ownerNodeId"],
        message: `Unknown component control owner: ${control.ownerNodeId}`,
      });
    }
    if (control.type === "branch") {
      const caseIds = new Set<string>();
      control.cases.forEach((branchCase, caseIndex) => {
        if (caseIds.has(branchCase.caseId)) {
          issues.push({
            code: "custom",
            path: ["layoutContext", "controls", index, "cases", caseIndex, "caseId"],
            message: `Duplicate component control case: ${branchCase.caseId}`,
          });
        }
        caseIds.add(branchCase.caseId);
      });
    }
  });

  const registryIds = new Set<string>();
  (graph.layoutContext.auxiliaryDefinitions ?? []).forEach((auxiliary, index) => {
    if (registryIds.has(auxiliary.definitionId)) {
      issues.push({
        code: "custom",
        path: ["layoutContext", "auxiliaryDefinitions", index, "definitionId"],
        message: `Duplicate auxiliary definition: ${auxiliary.definitionId}`,
      });
    }
    registryIds.add(auxiliary.definitionId);
  });

  const validateRuleset = (ruleset: DiagramRouteRequirementRuleset, issuePath: (string | number)[]) => {
    ruleset.forEach((rule, ruleIndex) => {
      const values = new Map<string, string>();
      rule.forEach((requirement, requirementIndex) => {
        const previous = values.get(requirement.controlId);
        if (previous !== undefined && previous !== requirement.value) {
          issues.push({
            code: "custom",
            path: [...issuePath, ruleIndex, requirementIndex],
            message: `Contradictory rule for control: ${requirement.controlId}`,
          });
        }
        values.set(requirement.controlId, requirement.value);
        const control = controlsById.get(requirement.controlId);
        if (!control) {
          issues.push({
            code: "custom",
            path: [...issuePath, ruleIndex, requirementIndex, "controlId"],
            message: `Unknown component control: ${requirement.controlId}`,
          });
        } else if (
          control.type === "conditional"
            ? requirement.value !== "on" && requirement.value !== "off"
            : !control.cases.some((branchCase) => branchCase.caseId === requirement.value)
        ) {
          issues.push({
            code: "custom",
            path: [...issuePath, ruleIndex, requirementIndex, "value"],
            message: `Invalid value for component control ${requirement.controlId}: ${requirement.value}`,
          });
        }
      });
    });
  };

  graph.edges.forEach((edge, index) => {
    if (edge.type === "control") validateRuleset(edge.activeWhen, ["edges", index, "activeWhen"]);
  });
  controls.forEach((control, index) => {
    if (control.dependsOn) validateRuleset(control.dependsOn, ["layoutContext", "controls", index, "dependsOn"]);
  });

  const targetsWithIncoming = new Set(graph.edges.map((edge) => edge.targetNodeId));
  graph.nodes.forEach((node, index) => {
    if (!targetsWithIncoming.has(node.nodeId) && !rootIds.has(node.nodeId)) {
      issues.push({
        code: "custom",
        path: ["nodes", index, "nodeId"],
        message: `Component node without incoming edges must be a declared root: ${node.nodeId}`,
      });
    }
  });

  const visited = new Set<string>();
  const visiting = new Set<string>();
  const hasCycle = (id: string): boolean => {
    if (visiting.has(id)) return true;
    if (visited.has(id)) return false;
    visiting.add(id);
    for (const path of controlsById.get(id)?.dependsOn ?? []) {
      for (const condition of path) if (hasCycle(condition.controlId)) return true;
    }
    visiting.delete(id);
    visited.add(id);
    return false;
  };
  if ([...controlsById.keys()].some(hasCycle)) {
    issues.push({
      code: "custom",
      path: ["layoutContext", "controls"],
      message: "Component control prerequisites contain a cycle",
    });
  }
  return issues;
}

export const componentStructureDiagramGraphSchema = z
  .object({
    ...graphBaseShape,
    groups: z.array(defaultDiagramGroupSchema).readonly(),
    nodes: z.array(componentStructureDiagramNodeSchema).min(1).readonly(),
    edges: z
      .array(z.discriminatedUnion("type", [componentStructureDefaultEdgeSchema, componentStructureControlEdgeSchema]))
      .readonly(),
    layoutContext: componentStructureLayoutContextSchema,
  })
  .strict()
  .superRefine((graph, context) => {
    for (const issue of validateComponentStructureGraph(graph)) context.addIssue(issue);
  })
  .meta({ id: "ComponentStructureGraph" });
export type ComponentStructureDiagramGraph = z.infer<typeof componentStructureDiagramGraphSchema>;

/* === Serialization === */

/** Stored graphs record the synthetic marker only where a generator set it, dropping the parse default. */
type WithoutSyntheticMarker<T> = T extends { synthetic: boolean } ? Omit<T, "synthetic"> : T;
const omitDefaultSynthetic = <T extends { synthetic: boolean }>(element: T): T | WithoutSyntheticMarker<T> => {
  const { synthetic: _synthetic, ...withoutMarker } = element;
  return (element.synthetic ? element : withoutMarker) as T | WithoutSyntheticMarker<T>;
};

export function toDiagramGraphInput(
  graph: ComponentStructureDiagramGraph,
): z.input<typeof componentStructureDiagramGraphSchema>;
export function toDiagramGraphInput(graph: SequenceDiagramGraph): z.input<typeof sequenceDiagramGraphSchema>;
export function toDiagramGraphInput(graph: DependencyDiagramGraph): z.input<typeof dependencyDiagramGraphSchema>;
export function toDiagramGraphInput(graph: FlowchartDiagramGraph): z.input<typeof flowchartDiagramGraphSchema>;
export function toDiagramGraphInput(graph: GeneralDiagramGraph): z.input<typeof generalDiagramGraphSchema>;
export function toDiagramGraphInput(
  graph: GeneralDiagramGraph | FlowchartDiagramGraph | ComponentStructureDiagramGraph,
):
  | z.input<typeof generalDiagramGraphSchema>
  | z.input<typeof flowchartDiagramGraphSchema>
  | z.input<typeof componentStructureDiagramGraphSchema> {
  if ("layoutContext" in graph) {
    const { auxiliaryDefinitions, controls, ...layoutContext } = graph.layoutContext;
    return {
      groups: graph.groups.map(({ type: _type, ...group }) => omitDefaultSynthetic(group)),
      nodes: graph.nodes.map(({ type: _type, ...node }) => omitDefaultSynthetic(node)),
      edges: graph.edges.map(({ layoutContext: edgeContext, ...edge }) => {
        const context = edgeContext.composition === null ? {} : { layoutContext: edgeContext };
        if (edge.type === "default") {
          const { type: _type, ...relationship } = edge;
          return { ...relationship, ...context };
        }
        return { ...edge, ...context };
      }),
      layoutContext: {
        ...layoutContext,
        controls: controls.map(({ dependsOn, ...control }) => {
          const prerequisites = dependsOn.length === 1 && dependsOn.at(0)!.length === 0 ? {} : { dependsOn };
          if (control.type === "branch" && !control.polarityPair) {
            const { polarityPair: _polarityPair, ...branch } = control;
            return { ...branch, ...prerequisites };
          }
          return { ...control, ...prerequisites };
        }),
        ...(auxiliaryDefinitions.length > 0 ? { auxiliaryDefinitions } : {}),
      },
    };
  }

  return {
    groups: graph.groups.map((group) => {
      if (group.type === "default") {
        const { type: _type, ...input } = group;
        return omitDefaultSynthetic(input);
      }
      if (!group.hideTitle) {
        const { hideTitle: _hideTitle, ...input } = group;
        return omitDefaultSynthetic(input);
      }
      return omitDefaultSynthetic(group);
    }),
    nodes: graph.nodes.map((node) => {
      if (node.type !== "default") return omitDefaultSynthetic(node);
      const { type: _type, ...input } = node;
      return omitDefaultSynthetic(input);
    }),
    edges: graph.edges.map((edge) => {
      if (edge.type === "default") {
        const { type: _type, ...input } = edge;
        return input;
      }
      if (edge.type === "message" && edge.messageType === "sync") {
        const { messageType: _messageType, ...input } = edge;
        return input;
      }
      return edge;
    }),
  };
}
